#![cfg(feature = "moderation-advanced")]
//! Isolated fresh-process hot-match sample; fixture is generated by actual TS.
use dima_rust::utils::js_string::JsString;
use dima_rust::utils::moderation::advanced::{
    Boundary, ModerationMatch, ModerationPattern, PatternCache, find_blacklist_matches_with_cache,
};
use serde_json::{Value, json};
use std::{env, fs, hint::black_box, path::Path, time::Instant};
#[path = "support/sha256.rs"]
mod digest;

fn string(v: &Value) -> JsString {
    JsString::from_units(
        v.as_array()
            .unwrap()
            .iter()
            .map(|x| u16::try_from(x.as_u64().unwrap()).unwrap())
            .collect(),
    )
}
fn wire(result: &[ModerationMatch]) -> Value {
    Value::Array(result.iter().map(|m| json!({"matcherID":m.matcher_id.units(),"text":m.text.units(),"start":m.start,"end":m.end})).collect())
}
fn checksum(results: &[Vec<ModerationMatch>]) -> u32 {
    let mut h = 2_166_136_261u32;
    let mut add = |n: u32| h = (h ^ n).wrapping_mul(16_777_619);
    for result in results {
        add(result.len() as u32);
        for m in result {
            for unit in m.matcher_id.code_units() {
                add(unit as u32);
            }
            add(65_536);
            for unit in m.text.code_units() {
                add(unit as u32);
            }
            add(65_536);
            add(m.start as u32);
            add(m.end as u32);
        }
        add(65_537);
    }
    h
}
struct Case {
    text: JsString,
    terms: Vec<JsString>,
    patterns: Vec<ModerationPattern>,
}
#[test]
#[ignore = "isolated release benchmark sample"]
fn benchmark_sample() {
    let filename = env::var("DIMA_ADVANCED_BENCHMARK_FIXTURE").unwrap();
    let path = Path::new(&filename);
    assert!(path.is_absolute());
    let real = fs::canonicalize(path).unwrap();
    let workspace =
        fs::canonicalize(Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap()).unwrap();
    assert!(!real.starts_with(workspace));
    let bytes = fs::read(real).unwrap();
    let hash = digest::sha256_hex(&bytes);
    let expected_hash = env::var("DIMA_ADVANCED_BENCHMARK_SHA256").unwrap();
    assert!(
        expected_hash.len() == 64
            && expected_hash
                .bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
    );
    assert_eq!(hash, expected_hash);
    let data: Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(data["format"], 1);
    let workload = env::var("DIMA_ADVANCED_BENCH_WORKLOAD").unwrap();
    assert!(["ascii", "long", "unicode", "regex_only", "many"].contains(&workload.as_str()));
    let prepare = |cases: &[Value]| -> Vec<Case> {
        cases
            .iter()
            .map(|c| Case {
                text: string(&c["text"]),
                terms: c["terms"].as_array().unwrap().iter().map(string).collect(),
                patterns: c["patterns"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| ModerationPattern {
                        id: string(&p["id"]),
                        source: string(&p["source"]),
                        boundary: match p["boundary"].as_str().unwrap() {
                            "whole_word" => Boundary::WholeWord,
                            "anywhere" => Boundary::Anywhere,
                            _ => panic!("invalid boundary"),
                        },
                        ignore_case: p["ignoreCase"].as_bool().unwrap(),
                    })
                    .collect(),
            })
            .collect()
    };
    // Fail before timing on any workload mismatch, not just the selected one.
    for name in ["ascii", "long", "unicode", "regex_only", "many"] {
        let source_cases = data["workloads"][name].as_array().unwrap();
        assert_eq!(source_cases.len(), 32);
        let validation_pool = prepare(source_cases);
        let validation_cache = PatternCache::new();
        for (case, expected) in validation_pool.iter().zip(source_cases) {
            let actual = find_blacklist_matches_with_cache(
                &case.text,
                &case.terms,
                &case.patterns,
                &validation_cache,
            )
            .unwrap();
            assert_eq!(wire(&actual), expected["result"]);
        }
        assert!(validation_cache.len() < 1000);
    }
    let cases = data["workloads"][&workload].as_array().unwrap();
    let pool = prepare(cases);
    let rounds: usize = env::var("DIMA_ADVANCED_BENCH_ROUNDS")
        .unwrap_or_else(|_| "250".into())
        .parse()
        .unwrap();
    assert!((1..=500).contains(&rounds));
    let cache = PatternCache::new();
    // Compare all ordered fields as UTF-16 arrays, preserving malformed strings.
    for (case, expected) in pool.iter().zip(cases) {
        let actual =
            find_blacklist_matches_with_cache(&case.text, &case.terms, &case.patterns, &cache)
                .unwrap();
        assert_eq!(wire(&actual), expected["result"]);
    }
    assert!(cache.len() < 1000);
    let count = rounds * pool.len();
    for _ in 0..3 {
        let mut retained = Vec::with_capacity(count);
        for _ in 0..rounds {
            for c in &pool {
                retained.push(black_box(
                    find_blacklist_matches_with_cache(
                        black_box(&c.text),
                        black_box(&c.terms),
                        black_box(&c.patterns),
                        black_box(&cache),
                    )
                    .unwrap(),
                ));
            }
        }
        assert_eq!(retained.len(), count);
        drop(retained);
    }
    let mut results = Vec::with_capacity(count);
    let start = Instant::now();
    for _ in 0..rounds {
        for c in &pool {
            results.push(black_box(
                find_blacklist_matches_with_cache(
                    black_box(&c.text),
                    black_box(&c.terms),
                    black_box(&c.patterns),
                    black_box(&cache),
                )
                .unwrap(),
            ));
        }
    }
    let elapsed = start.elapsed().as_nanos();
    for (i, actual) in results.iter().enumerate() {
        assert_eq!(wire(actual), cases[i % 32]["result"]);
    }
    let report = json!({"format":1,"actor":"rust","workload":workload,"rounds":rounds,"operations":count,"warmups":3,"warmupOperations":count*3,"nanoseconds":elapsed.to_string(),"checksum":checksum(&results),"inputSha256":hash});
    println!("{}", report);
}
